from abc import ABC, abstractmethod

# The sacred blueprint, the SortAlgorithm, a template for the earthly order.
class SortAlgorithm(ABC):
    @abstractmethod
    def sort(self, data):
        """The sacred ritual of sorting, the skeleton of the process."""
        pass

    @abstractmethod
    def compare(self, a, b):
        """The divine judgment, determining the rightful place of each element."""
        pass

    @abstractmethod
    def swap(self, data, i, j):
        """The cosmic realignment, exchanging positions as decreed."""
        pass

# The BubbleSort, a simple, yet effective, method of rising above the dross.
class BubbleSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)
        return data

    def compare(self, a, b):
        # For integers, the lesser ascends. For strings, the alphabetically prior.
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# The SelectionSort, a more deliberate, yet equally vital, process of choosing.
class SelectionSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(data[j], data[min_idx]):
                    min_idx = j
            self.swap(data, i, min_idx)
        return data

    def compare(self, a, b):
        return a > b

    def swap(self, data, i, j):
        data[i], data[j] = data[j], data[i]

# Now, let us witness the earthly sorting, a prelude to the divine purification!
if __name__ == "__main__":
