    bubble_sorter = BubbleSort()
    sorted_numbers_bubble = bubble_sorter.sort(numbers.copy())
    print("BubbleSort's divine order:", sorted_numbers_bubble)

    # The SelectionSort, choosing the path of least resistance.
    selection_sorter = SelectionSort()
